from pathlib import Path
from html.parser import HTMLParser
import sys

ROOT = Path("/private/var/folders/pt/6z2c_t0x3nl8ng09lpdz61340000gp/T/sitegen-runs/B05")

class LinkExtractor(HTMLParser):
    def __init__(self, page_path, root):
        super().__init__()
        self.page_path = page_path
        self.root = root
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == "a":
            for name, value in attrs:
                if name == "href":
                    self.links.append(value)
        elif tag == "link":
            for name, value in attrs:
                if name == "href":
                    self.links.append(value)

errors = []
all_links = []

for html_file in sorted((ROOT / "out").rglob("*.html")):
    parser = LinkExtractor(html_file, ROOT / "out")
    parser.feed(html_file.read_text())

    for link in parser.links:
        # Skip fragment-only or external links
        if link.startswith("#") or link.startswith("http://") or link.startswith("https://"):
            continue

        resolved = (html_file.parent / link).resolve()
        all_links.append((str(html_file.relative_to(ROOT / "out")), link, str(resolved.relative_to(ROOT / "out"))))
        if not resolved.exists():
            errors.append(f"{html_file.relative_to(ROOT / 'out')}: broken link -> {link} (resolved: {resolved})")

print("=== All links found ===")
for page, link, resolved in all_links:
    print(f"  {page} -> {link}  =>  {resolved}")

print()
if errors:
    print("=== BROKEN LINKS ===")
    for e in errors:
        print(f"  {e}")
    sys.exit(1)
else:
    print(f"=== All {len(all_links)} links valid ===")
